// Requirements: Store, Menu, Path (breadcrumb)
import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.describe('Store', () => {
  test('shopper sees the store name', async ({ page }) => {
    await expect(page.getByRole('banner')).toBeVisible();
    await expect(page.getByRole('link', { name: 'Stride' })).toBeVisible();
  });

  test('shopper sees how many items are in their cart', async ({ page }) => {
    await expect(page.getByTestId('cart-count')).toHaveText('0');
  });
});

test.describe('Menu', () => {
  test('shopper can reach the main sections from the top of the page', async ({ page }) => {
    const menu = page.getByRole('navigation', { name: /main/i });
    await expect(menu.getByRole('link', { name: 'Men', exact: true })).toBeVisible();
    await expect(menu.getByRole('link', { name: 'Women', exact: true })).toBeVisible();
    await expect(menu.getByRole('link', { name: 'Kids', exact: true })).toBeVisible();
  });
});

test.describe('Path', () => {
  test('shopper sees where the shoe sits in the store', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb.getByText('Shop')).toBeVisible();
    await expect(breadcrumb.getByText('Trail', { exact: true })).toBeVisible();
    await expect(breadcrumb.getByText('Trail Runner 2')).toBeVisible();
  });

  test('shopper can go back to any earlier step', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb.getByRole('link', { name: 'Shop' })).toHaveAttribute('href', /\//);
    await expect(breadcrumb.getByRole('link', { name: 'Trail', exact: true })).toHaveAttribute(
      'href',
      /\//,
    );
    // The current step is not a link back to itself.
    await expect(breadcrumb.getByRole('link', { name: 'Trail Runner 2' })).toHaveCount(0);
    await expect(breadcrumb.getByText('Trail Runner 2')).toHaveAttribute('aria-current', 'page');
  });
});

