// Requirement: Photos
import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.describe('Photos', () => {
  test('shopper sees one photo of the shoe at a time', async ({ page }) => {
    const gallery = page.getByRole('region', { name: /product photos/i });
    await expect(gallery.getByRole('img')).toHaveCount(1);
    await expect(gallery.getByRole('img')).toHaveAttribute(
      'alt',
      'Trail Runner 2 photo 1 of 3',
    );
  });

  test('shopper moves to the next and previous photo', async ({ page }) => {
    const gallery = page.getByRole('region', { name: /product photos/i });
    const img = gallery.getByRole('img');

    await gallery.getByRole('button', { name: /next photo/i }).click();
    await expect(img).toHaveAttribute('alt', 'Trail Runner 2 photo 2 of 3');
    await expect(gallery.getByRole('img')).toHaveCount(1);

    await gallery.getByRole('button', { name: /previous photo/i }).click();
    await expect(img).toHaveAttribute('alt', 'Trail Runner 2 photo 1 of 3');
  });

  test('gallery wraps back to the first photo after the last', async ({ page }) => {
    const gallery = page.getByRole('region', { name: /product photos/i });
    const img = gallery.getByRole('img');
    const next = gallery.getByRole('button', { name: /next photo/i });

    await next.click();
    await next.click();
    await expect(img).toHaveAttribute('alt', 'Trail Runner 2 photo 3 of 3');

    await next.click();
    await expect(img).toHaveAttribute('alt', 'Trail Runner 2 photo 1 of 3');

    // And wraps back to the last photo before the first.
    await gallery.getByRole('button', { name: /previous photo/i }).click();
    await expect(img).toHaveAttribute('alt', 'Trail Runner 2 photo 3 of 3');
  });
});

