// Requirements: Price, Color, Size, Size guide, Quantity, Add to cart, Wishlist
import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.describe('Price', () => {
  test('shopper sees the price', async ({ page }) => {
    await expect(page.getByTestId('price')).toHaveText('$120.00');
  });

  test('pointing at the "i" next to the price explains that taxes are included', async ({
    page,
  }) => {
    await page.getByRole('button', { name: /price information/i }).hover();
    await expect(page.getByRole('tooltip')).toContainText(/includes taxes/i);
  });
});

test.describe('Color', () => {
  test('shopper can choose blue, black or grey, each with a round swatch', async ({ page }) => {
    const colors = page.getByRole('group', { name: /color/i });
    for (const name of ['Blue', 'Black', 'Grey']) {
      const swatch = colors.getByRole('button', { name, exact: true });
      await expect(swatch).toBeVisible();
      const radius = await swatch.evaluate(
        (el) => getComputedStyle(el).borderTopLeftRadius,
      );
      expect(radius).not.toBe('0px');
    }
  });

  test('only the chosen color shows until the shopper changes it', async ({ page }) => {
    const colors = page.getByRole('group', { name: /color/i });

    // Blue is selected by default; only it is shown as the chosen color.
    await expect(colors.getByRole('button', { name: 'Blue', exact: true })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    await expect(page.getByTestId('selected-color')).toHaveText('Blue');

    await colors.getByRole('button', { name: 'Black', exact: true }).click();
    await expect(page.getByTestId('selected-color')).toHaveText('Black');
    await expect(colors.getByRole('button', { name: 'Black', exact: true })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    await expect(colors.getByRole('button', { name: 'Blue', exact: true })).toHaveAttribute(
      'aria-pressed',
      'false',
    );

    await colors.getByRole('button', { name: 'Grey', exact: true }).click();
    await expect(page.getByTestId('selected-color')).toHaveText('Grey');
  });
});

test.describe('Size', () => {
  test('size list only opens when the shopper wants to change it', async ({ page }) => {
    await expect(page.getByRole('listbox')).toHaveCount(0);

    await page.getByRole('button', { name: /select size/i }).click();
    const listbox = page.getByRole('listbox');
    await expect(listbox).toBeVisible();

    await listbox.getByRole('option', { name: 'US 8', exact: true }).click();

    // The list closes and only the chosen size shows.
    await expect(page.getByRole('listbox')).toHaveCount(0);
    await expect(page.getByRole('button', { name: /size: us 8/i })).toBeVisible();
  });

  test('sold-out sizes cannot be picked', async ({ page }) => {
    await page.getByRole('button', { name: /select size/i }).click();
