// Requirements: More information, Questions, Bottom of the page
import { test, expect } from '@playwright/test';

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.describe('More information', () => {
  test('details, reviews and shipping sit side by side below everything', async ({ page }) => {
    const tablist = page.getByRole('tablist', { name: /more information/i });
    await expect(tablist.getByRole('tab', { name: 'Details' })).toBeVisible();
    await expect(tablist.getByRole('tab', { name: 'Reviews' })).toBeVisible();
    await expect(tablist.getByRole('tab', { name: 'Shipping' })).toBeVisible();

    // Below everything: the tabs sit under the add-to-cart area of the page.
    const tabsBox = await tablist.boundingBox();
    const buyBox = await page.getByRole('button', { name: /add to cart/i }).boundingBox();
    expect(tabsBox.y).toBeGreaterThan(buyBox.y);

    // Side by side: the tabs share the same row.
    const tabs = tablist.getByRole('tab');
    const rows = new Set();
    for (const tab of await tabs.all()) {
      rows.add(Math.round((await tab.boundingBox()).y));
    }
    expect(rows.size).toBe(1);
  });

  test('one section is shown at a time', async ({ page }) => {
    const tablist = page.getByRole('tablist', { name: /more information/i });

    // Details is shown first.
    await expect(page.getByRole('tabpanel')).toHaveCount(1);
    await expect(page.getByRole('tabpanel')).toContainText(/breathable mesh/i);

    await tablist.getByRole('tab', { name: 'Reviews' }).click();
    await expect(page.getByRole('tabpanel')).toHaveCount(1);
    await expect(page.getByRole('tabpanel')).toContainText(/4\.5/);
    await expect(page.getByRole('tabpanel')).not.toContainText(/breathable mesh/i);

    await tablist.getByRole('tab', { name: 'Shipping' }).click();
    await expect(page.getByRole('tabpanel')).toHaveCount(1);
    await expect(page.getByRole('tabpanel')).toContainText(/free shipping/i);
  });
});

test.describe('Questions', () => {
  const questions = [
    {
      question: 'Is the Trail Runner 2 waterproof?',
      answer: /water-repellent/i,
    },
    {
      question: 'How much does the Trail Runner 2 weigh?',
      answer: /260\s?g/i,
    },
    {
      question: 'Can I machine wash the Trail Runner 2?',
      answer: /hand wash/i,
    },
  ];

  test('each answer is hidden until the shopper opens the question', async ({ page }) => {
    for (const { question, answer } of questions) {
      const toggle = page.getByRole('button', { name: question });
      await expect(toggle).toBeVisible();
      await expect(toggle).toHaveAttribute('aria-expanded', 'false');
      await expect(page.getByText(answer)).toBeHidden();

      await toggle.click();
      await expect(toggle).toHaveAttribute('aria-expanded', 'true');
      await expect(page.getByText(answer)).toBeVisible();

      await toggle.click();
      await expect(toggle).toHaveAttribute('aria-expanded', 'false');
      await expect(page.getByText(answer)).toBeHidden();
    }
  });
});

test.describe('Bottom of the page', () => {
  test('shopper finds customer help, company and social media links', async ({ page }) => {
    const footer = page.getByRole('contentinfo');

    const help = footer.getByRole('navigation', { name: /customer help/i });
    await expect(help.getByRole('link', { name: /contact us/i })).toBeVisible();
    await expect(help.getByRole('link', { name: /shipping & returns/i })).toBeVisible();
    await expect(help.getByRole('link', { name: /faq/i })).toBeVisible();

    const company = footer.getByRole('navigation', { name: /company/i });
    await expect(company.getByRole('link', { name: /about us/i })).toBeVisible();
    await expect(company.getByRole('link', { name: /careers/i })).toBeVisible();
    await expect(company.getByRole('link', { name: /press/i })).toBeVisible();

    const social = footer.getByRole('navigation', { name: /social media/i });
    await expect(social.getByRole('link', { name: /instagram/i })).toBeVisible();
    await expect(social.getByRole('link', { name: /facebook/i })).toBeVisible();
    await expect(social.getByRole('link', { name: /x \(twitter\)/i })).toBeVisible();
  });

  test('footer links point somewhere', async ({ page }) => {
    const footer = page.getByRole('contentinfo');
    await expect(footer.getByRole('link').first()).toBeVisible();
    for (const link of await footer.getByRole('link').all()) {
      await expect(link).toHaveAttribute('href', /.+/);
    }
  });
});
